"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[17205],{17205:e=>{e.exports=JSON.parse('{"_status":"machine-draft, needs human review","Addis Ababa Fistula Hospital":"ሆስፒታል ፊስቱላ ኣዲስ ኣበባ","Alert Hospital – Addis Ababa":"ሆስፒታል ኣለርት – ኣዲስ ኣበባ","Black Lion Hospital (Tikur Anbessa) – Addis Ababa":"ሆስፒታል ጥቑር ኣንበሳ – ኣዲስ ኣበባ","Call emergency services immediately":"ብቕልጡፍ ናብ ህጹጽ ኣገልግሎት ደውል","Do NOT administer any herbs — proceed to hospital only":"ዝኾነ ኣትክልቲ ኣይትሃብ — ናብ ሆስፒታል ጥራይ ኪድ","Do NOT give iron tablets without medical supervision":"ብዘይ ሕክምናዊ ቁጽጽር ናይ ሓጺን ከኒና ኣይትሃብ","Emergency Wellbeing Profile | Ethiopian Wisdom Platform":"ናይ ህጹጽ ጥዕና መግለጺ | መድረኽ ጥበብ ኢትዮጵያ","Ensure patient is lying down in a safe position":"እቲ ሕሙም ብውሑስ ኣቀማምጣ ከም ዝደቀሰ ኣረጋግጽ","Felege Hiwot Referral Hospital – Amhara":"ሆስፒታል ሪፈራል ፈለገ ሕይወት – ኣምሓራ","Give 15g fast-acting carbohydrate: 3–4 tsp sugar dissolved in water":"15 ግራም ቀልጢፉ ዝሰርሕ ካርቦሃይድሬት ሃብ፦ 3–4 ማንካ ሻሂ ሽኮር ኣብ ማይ ዝሓቐቐ","Harar Hospital – Harari":"ሆስፒታል ሓረር – ሓረሪ","Hawassa University Referral Hospital – Sidama":"ሆስፒታል ሪፈራል ዩኒቨርሲቲ ሃዋሳ – ሲዳማ","Identify and remove allergen source immediately":"ምንጪ ኣለርጂ ብቕልጡፍ ለይካ ኣርሕቕ","If prescribed epinephrine auto-injector is available, use it":"ዝተኣዘዘ ናይ ኤፒነፍሪን ባዕሉ ዝወግእ መርፍእ እንተሎ ተጠቐመሉ","If unconscious, place in recovery position (left side)":"ልቡ እንተ ኣዕሪፉ ኣብ ናይ ምምሕያሽ ኣቀማምጣ (ብጸጋማይ ጎኑ) ኣደቕሶ","Jimma University Medical Center – Oromia":"ማእከል ሕክምና ዩኒቨርሲቲ ጅማ – ኦሮምያ","Keep patient warm — blanket if available":"ነቲ ሕሙም ኣሙቖ — ኮበርታ እንተሎ","Kosso/Gesho contraindicated — avoid all herbs during hypoglycemia":"ኮሶ/ጌሾ ኣይምከሩን — ሽኮር ደም ኣብ ዝወረደሉ ኩሉ ኣትክልቲ ኣወግድ","Lie patient flat — legs elevated unless breathing is difficult":"ነቲ ሕሙም ብዝባኑ ኣደቕሶ — ምስትንፋስ እንተዘይከቢዱ ኣእጋሩ ልዕል ኣብሎ","Low Blood Sugar Response":"ምላሽ ንትሑት ሽኮር ደም","Mekelle Hospital – Tigray":"ሆስፒታል መቐለ – ትግራይ","Recheck in 15 minutes — repeat if not improved":"ድሕሪ 15 ደቒቕ ደጊምካ ኣረጋግጽ — እንተ ዘይተመሓይሹ ድገሞ","Seek medical help if unresponsive":"መልሲ እንተዘይሂቡ ሕክምናዊ ሓገዝ ድለ","Set up your emergency wellbeing profile — contacts, conditions, medications, and blood type — so first responders can act quickly in a wellbeing emergency.":"ናይ ህጹጽ ጥዕና መግለጺኻ ኣዳሉ — ኣድራሻታት፣ ኩነታት ጥዕና፣ መድሃኒታትን ዓይነት ደምን — ቀዳማይ ረዲኤት ዝህቡ ሰባት ኣብ ህጹጽ ኩነታት ቀልጢፎም ክሰርሑ ምእንቲ።","Severe Allergic Reaction (Anaphylaxis)":"ምላሽ ንከቢድ ኣለርጂ (ኣናፊላክሲስ)","Severe Anemia Response":"ምላሽ ንከቢድ ሕጽረት ደም","St. Paul\'s Hospital Millennium Medical College – Addis Ababa":"ሆስፒታል ቅዱስ ጳውሎስ ሚሌንየም ሕክምና ኮሌጅ – ኣዲስ ኣበባ","Traditional option: 1 tsp honey (ማር) in warm water":"ባህላዊ ምርጫ፦ 1 ማንካ ሻሂ መዓር ኣብ ዝሞቐ ማይ","Unknown":"ዘይተፈልጠ","Yekatit 12 Hospital – Addis Ababa":"ሆስፒታል የካቲት 12 – ኣዲስ ኣበባ","⚠️ Do NOT administer herbal remedies during acute crisis":"⚠️ ኣብ እዋን ኣጣዳፊ ቅልውላው ናይ ኣትክልቲ መድሃኒት ኣይትሃብ"}')}}]);